		int x, y; cin >> x >> y;
		e[x].push_back(y);
		e[y].push_back(x);
	}
	int nd = 0;
	for(int i = 0; i < max_time; i++){
		for(int j = 1; j <= n; j++) to[i][j] = nd++;
	}
	int S = nd++, T = nd++;
	SSP flow(nd, S, T);
	for(int i = 0; i < k; i++) flow.add_edge(S, to[0][a[i]], 1, 0);
	for(int i = 0; i < max_time; i++) flow.add_edge(to[i][1], T, k, c * i);
	for(int i = 0; i < max_time - 1; i++){
		for(int j = 1; j <= n; j++){
			for(int k : e[j]){
				for(int z = 0; z <= 52; z++){
					flow.add_edge(to[i][j], to[i + 1][k], 1, d * (2 * z + 1));
				}	
			}
			flow.add_edge(to[i][j], to[i + 1][j], k, 0);
		}
	}
	int p0, p1; tie(p0, p1) = flow.mfmc();
	cout << p1 << endl;
	return 0;
}

