class SSP:
    def __init__(self, n, source, sink):
        self.n = n
        self.source = source
        self.sink = sink
        self.adj = [[] for _ in range(n)]
        self.edges = []

    class edge:
        def __init__(self, u, flow, cap, cost, origcost):
            self.u = u
            self.flow = flow
            self.cap = cap
            self.cost = cost
            self.origcost = origcost

    def add_edge(self, a, b, cap, cost):
        result = len(self.edges)
        self.adj[a].append(len(self.edges))
        self.edges.append(self.edge(b, 0, cap, cost, cost))
        self.adj[b].append(len(self.edges))
        self.edges.append(self.edge(a, 0, 0, -cost, -cost))
        return result

    def djk(self):
        import heapq
        class state_t:
            def __init__(self, dist, prev, maxf):
                self.dist = dist
                self.prev = prev
                self.maxf = maxf

        n = self.n
        dist = [float('inf')] * n
        prev = [-1] * n
        maxf = [0] * n
        dist[self.source] = 0
        maxf[self.source] = float('inf')
        pq = []
        heapq.heappush(pq, (dist[self.source], self.source))
        while pq:
            d, v = heapq.heappop(pq)
            if d != dist[v]:
                continue
            for edid in self.adj[v]:
                ed = self.edges[edid]
                if ed.flow < ed.cap and dist[ed.u] > dist[v] + ed.cost:
                    dist[ed.u] = dist[v] + ed.cost
                    prev[ed.u] = edid
                    maxf[ed.u] = min(maxf[v], ed.cap - ed.flow)
                    heapq.heappush(pq, (dist[ed.u], ed.u))
        lastid = prev[self.sink]
        extraflow = maxf[self.sink]
        atcost = 0
        if lastid == -1:
            return (0, 0)
        id_ = lastid
        while id_ != -2:
            self.edges[id_].flow += extraflow
            self.edges[id_ ^ 1].flow -= extraflow
            atcost += self.edges[id_].origcost
            id_ = prev[self.edges[id_ ^ 1].u]
        for id_, ed in enumerate(self.edges):
            v = self.edges[id_ ^ 1].u
            u = ed.u
            if prev[v] != -1 and prev[u] != -1:
                ed.cost += dist[v] - dist[u]
        return (extraflow, atcost)

    def mfmc(self):
        flow = 0
        cost = 0
        def any_negative_cycle():
            return any(ed.flow > 0 and ed.cost < 0 for ed in self.edges)

        if any_negative_cycle():
            self.bellamanford()

        while True:
            extraflow, atcost = self.djk()
            if extraflow <= 0:
                break
            flow += extraflow
            cost += extraflow * atcost
        return flow, cost

    def bellamanford(self):
        dist = [float('inf')] * self.n
        dist[self.source] = 0
        for _ in range(self.n):
            changed = False
            for id_, ed in enumerate(self.edges):
                v = self.edges[id_ ^ 1].u
                u = ed.u
                if ed.flow < ed.cap and dist[v] != float('inf') and dist[u] > dist[v] + ed.cost:
                    dist[u] = dist[v] + ed.cost
                    changed = True
            if not changed:
                break
        for id_, ed in enumerate(self.edges):
            v = self.edges[id_ ^ 1].u
            u = ed.u
            if dist[v] != float('inf') and dist[u] != float('inf'):
                ed.cost += dist[v] - dist[u]

