const long long INF = 1e14;


struct edge {
	int u, v;
	long long cap, flow;
	long long cost;
	long long rem() {
		return cap - flow;
	}
	edge(){}
	edge(int _u, int _v, long long _cap, long long _flow, long long _cost) {
		u = _u;
		v = _v;
		cap = _cap;
		flow = _flow;
		cost = _cost;
	}
};


int nodes; 
vector<int> g[MAXN];
vector<edge> e;


void add_edge(int u, int v, long long cap, long long cost) {
	g[u].pb(sz(e));
	e.pb(edge(u, v, cap, 0, cost));
	g[v].pb(sz(e));
	e.pb(edge(v, u, 0, 0, -cost));
}


long long dist[MAXN], mncost;
int pre[MAXN];
long long cap[MAXN], mxflow;
bool inq[MAXN];


void flow(int s, int t) {
	memset(inq, 0, sizeof(inq));
	mxflow = mncost = 0;
	while (true) {
		fill(dist, dist + nodes, INF);
		dist[s] = 0;
		memset(pre, -1, sizeof(pre));
		pre[s] = 0;
		memset(cap, 0, sizeof(cap));
		cap[s] = INF;
		queue<int> q;
		q.push(s);
		inq[s]=1;
		while (!q.empty()) {
			int u = q.front();
			q.pop();
			inq[u] = 0;
			for (int it = 0; it < sz(g[u]); it++) {
				int i = g[u][it];
				edge &f = e[i];
				if (f.rem() && dist[f.v] > dist[u] + f.cost + 1e-9) {
					dist[f.v] = dist[u] + f.cost;
					pre[f.v] = i;
					cap[f.v] = min(cap[u], f.rem());
					if (!inq[f.v]) {
						q.push(f.v);
						inq[f.v] = 1;
					}
				}
			}
		}
		if (pre[t] < 0) {
			break;
		}
		mxflow +=cap[t];
		mncost += cap[t] * dist[t];
		int v = t;
		while (v != s) {
			e[pre[v]].flow += cap[t];
			e[pre[v] ^ 1].flow -= cap[t];
			v = e[pre[v]].u;
		}
	}
}


