		addedge(S,x,1,0);
	}
	for (int i=0;i<lim;i++)
		addedge(i*n,T,k,c*i);
	for (int i=0;i<n;i++)
		for (int j=0;j<lim-1;j++)
			addedge(i+j*n,i+(j+1)*n,k,0);
	while (m--){
		int x,y; cin>>x>>y; x--,y--;
		for (int i=0;i<lim-1;i++)
			for (int j=k-1;~j;j--){
				addedge(x+i*n,y+(i+1)*n,1,d*(j<<1|1));
				addedge(y+i*n,x+(i+1)*n,1,d*(j<<1|1));
			}
	}
	cout<<costflow();
	return 0;
}

