    def adde(cls, u, v, c, w):
        cls.g[u].append(cls.edge(v, len(cls.g[v]), c, w))
        cls.g[v].append(cls.edge(u, len(cls.g[u]) -1, 0, -w))

    @classmethod
    def dijkstra(cls, s, t):
        for i in range(cls.n):
            cls.dis[i] = inf
            cls.vis[i] = 0
        q = []
        cls.dis[s] = 0
        heapq.heappush(q, (0, s))
        while q:
            du, u = heapq.heappop(q)
            if cls.vis[u]:
                continue
            cls.vis[u] = 1
            for e in cls.g[u]:
                v = e.v
                dv = du + cls.pot[u] + e.w - cls.pot[v]
                if not e.c or cls.vis[v] or cls.dis[v] <= dv:
                    continue
                cls.dis[v] = dv
                heapq.heappush(q, (cls.dis[v], v))
        return cls.vis[t]

    @classmethod
    def dinic_bfs(cls, s, t):
        for i in range(cls.n):
            cls.vis[i] = 0
        from collections import deque
        q = deque()
        q.append(s)
        cls.vis[s] = 1
        while q:
            u = q.popleft()
            for e in cls.g[u]:
                v = e.v
                if cls.vis[v] or not e.c:
                    continue
                if cls.dis[v] != cls.dis[u] + e.w - cls.pot[v] + cls.pot[u]:
                    continue
                cls.vis[v] = cls.vis[u] + 1
                q.append(v)
        return cls.vis[t] != 0

    @classmethod
    def dinic_dfs(cls, u, t, f, cur, dis, vis):
        if u == t:
            return f
        sf = 0
        while cur[u] < len(cls.g[u]):
            e = cls.g[u][cur[u]]
            v = e.v
            if not e.c or vis[v] != vis[u] + 1:
                cur[u] += 1
                continue
            if dis[v] != dis[u] + e.w - cls.pot[v] + cls.pot[u]:
                cur[u] += 1
                continue
            d = cls.dinic_dfs(v, t, min(e.c, f), cur, dis, vis)
            if d:
                e.c -= d
                cls.g[v][e.p].c += d
                sf += d
                f -= d
                if f == 0:
                    break
            cur[u] += 1
        return sf

    @classmethod
    def mincostflow(cls, s, t, mf):
        sf = 0
        sc = 0
        for i in range(cls.n):
            cls.pot[i] = 0
        while cls.dijkstra(s, t):
            for i in range(cls.n):
                cls.cur[i] = 0
            while True:
                cur = [0]*cls.n
                dis = [0]*cls.n
                for i in range(cls.n):
                    dis[i] = cls.dis[i]
                vis = [0]*cls.n
                f = cls.dinic_dfs(s, t, mf, cur, dis, vis)
                if f == 0:
                    break
                mf -= f
                sf += f
                sc += (cls.dis[t] + cls.pot[t]) * f
            for i in range(cls.n):
                cls.pot[i] += cls.dis[i]
            if mf == 0:
                break
        return (sf, sc)

def main():
    input = sys.stdin.read().strip().split()
    n, m, k, c, d = map(int, input[:5])
    rest = input[5:]
    l = max(n, k) * 2
    s = mcmf.addv(1)
    t = mcmf.addv(1)
    idx = 0
    for _ in range(k):
        a = int(rest[idx])
        idx += 1
        a -= 1
        mcmf.adde(s, a, 1, 0)
    for _ in range(m):
        u, v = int(rest[idx]), int(rest[idx+1])
        idx += 2
        u -= 1
        v -= 1
        for i in range(l -1):
            u1 = u + i * n
            v1 = v + (i + 1) * n
            u2 = u + (i + 1) * n
            v2 = v + i * n
            for j in range(k):
                cost_val = c + d * (2 * j + 1)
                mcmf.adde(u1, v1, 1, cost_val)
                mcmf.adde(v2, u2, 1, cost_val)
    for i in range(l -1):
        for j in range(n):
            u = j + i * n
            v_ = j + (i + 1) * n
            mcmf.adde(u, v_, inf, c)
    for i in range(l):
        mcmf.adde(i * n, t, inf, 0)

    flow, cost = mcmf.mincostflow(s, t, inf)
    print(cost)

