bool spfa() {
	memset(incf, 0, sizeof(incf)), memset(dis, INF, sizeof(dis));
	memset(inq, 0, sizeof(inq)); queue<int> q;
	q.push(s), incf[s] = INF, inq[s] = 1, dis[s] = 0;
	for(; !q.empty();) {
		int u = q.front(); q.pop(); inq[u] = 0;
		for(int i = hed[u]; i; i = nxt[i]) {
			if(!val[i] || dis[to[i]] <= dis[u] + w[i]) continue;
			dis[to[i]] = dis[u] + w[i];
			incf[to[i]] = min(incf[u], val[i]);
			pre[to[i]] = i; if(!inq[to[i]]) inq[to[i]] = 1, q.push(to[i]);
		}
	}
	return dis[t] != INF;
}
void update() {
	int tmp = t;
	for(; tmp != s;) {
		int i = pre[tmp];
		val[i] -= incf[t], val[i ^ 1] += incf[t], tmp = to[i ^ 1];
	}
	ans += incf[t] * dis[t];
}
