		for (int i = 0; i <= N; i++) C[i].resize(i + 1);
		for (int i = 0; i <= N; i++) C[i][i] = C[i][0] = 1;
		for (int i = 1; i <= N; i++) for (int j = 1; j < i; j++) C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD_COMB;
		F.resize(N + 1);
		F[0] = F[1] = 1;
		for (int i = 1; i <= n; i++) F[i] = (F[i - 1] * i) % MOD_COMB;
	}
