class PrimeNumber:
    def __init__(self, n):
        self.N=n
        self.NP = [0]*(N+4)
        self.P=[]
        for i in range(2, int(math.sqrt(N))+1):
            if self.NP[i]:
                continue
            for j in range(i*i, N+1, i):
                self.NP[j]=1
        for i in range(2, N+1):
            if not self.NP[i]:
                self.P.append(i)
    def gcd(self, x, y):
        while x:
            z=y%x
            y=x
            x=z
        return y
    def powermod(self, p, q):
        g=self.gcd(p, q)
        p//=g
        q//=g
        return (p * pow(q, -1, 10**9+7))%(10**9+7)

    def factorization(self, x):
        ret=[]
        if x==1:
            ret.append(1)
            return ret
        ret=[1,x]
        for i in range(2, int(math.sqrt(x))+1):
            if x%i==0:
                ret.append(i)
                ret.append(x//i)
        if int(math.sqrt(x))**2==x:
            ret.append(int(math.sqrt(x)))
        return ret

    def factorization2(self,x):
        ret=0
        if x==1:
            return 1
        ret=2
        for i in range(2, int(math.sqrt(x))+1):
            if x%i==0:
                ret+=2
        if int(math.sqrt(x))**2==x:
            ret+=1
        return ret

