class Sort:
    def __init__(self, n):
        self.N=n
        self.tmp=[]
    def merge_sort(self, x, lo, hi):
        if lo>=hi:
            return
        mid= (lo+hi)//2
        self.merge_sort(x, lo, mid)
        self.merge_sort(x, mid+1, hi)
        i, j, k=lo, mid+1, lo
        self.tmp = [0]*(hi-lo+1)
        while i<=mid and j<=hi:
            if x[i]<x[j]:
                self.tmp[k-lo]=x[i]
                i+=1
            else:
                self.tmp[k-lo]=x[j]
                j+=1
            k+=1
        while i<=mid:
            self.tmp[k-lo]=x[i]
            i+=1
            k+=1
        while j<=hi:
            self.tmp[k-lo]=x[j]
            j+=1
            k+=1
        for idx in range(lo, hi+1):
            x[idx]=self.tmp[idx - lo]

class PSum:
    def makeSum(self, a, n):
        ret= [0]*len(a)
        ret[0]=a[0]
        for i in range(1, len(a)):
            ret[i]=ret[i-1]+a[i]
        return ret
    def makeSum2(self, a, n, m):
        ret= [ [0]*m for _ in range(n)]
        for i in range(n):
            ret[i][0]=a[i][0]
        for i in range(n):
            for j in range(1,m):
                ret[i][j]=ret[i][j-1]+a[i][j]
        return ret
    def getSum(self, psum, a, b):
        if a==0:
            return psum[b]
        return psum[b]-psum[a-1]
    def getSum2(self, psum, r1, c1, r2, c2):
        ret=psum[r2][c2]
        if r1>0:
            ret-=psum[r1-1][c2]
        if c1>0:
            ret-=psum[r2][c1-1]
        if r1>0 and c1>0:
            ret+=psum[r1-1][c1-1]
        return ret

class DisjointSet:
    def __init__(self, n):
        self.N=n
        self.P= list(range(n+1))
        self.R= [0]*(n+1)
        self.A= [1]*(n+1)
    def getA(self, x):
        return self.A[x]
    def find_set(self, x):
        if self.P[x]==x:
            return x
        self.P[x]=self.find_set(self.P[x])
        return self.P[x]
    def union_set(self, x, y):
        px=self.find_set(x)
        py=self.find_set(y)
        if px==py:
            return px
        if self.R[px]>self.R[py]:
            self.P[py]=px
            self.A[px]+=self.A[py]
            return px
        else:
            self.P[px]=py
            self.A[py]+=self.A[px]
            if self.R[px]==self.R[py]:
                self.R[py]+=1
            return py

class LIS:
    def __init__(self, n):
        self.N=n
    def execute(self, A):
        v=[]
        for x in A:
            if not v or v[-1]<x:
                v.append(x)
            else:
                idx = self.lower_bound(v, x)
                v[idx]=x
        return len(v)
    def lower_bound(self, arr, target):
        lo, hi=0, len(arr)
        while lo<hi:
            mid=(lo+hi)//2
            if arr[mid]>=target:
                hi=mid
            else:
                lo=mid+1
        return lo
    def execute2(self, A):
        v=[]
        p=[-1]*len(A)
        v1=[]
        for i, x in enumerate(A):
            if not v or v[-1]<x:
                if v:
                    p[i]=v1[-1]
                v.append(x)
                v1.append(i)
            else:
                idx=self.lower_bound(v, x)
                v[idx]=x
                if idx>0:
                    p[i]=v1[idx-1]
                v1[idx]=i
        length=len(v1)
        ret=[0]*length
        i=v1[-1]
        for j in range(length-1,-1,-1):
            ret[j]=A[i]
            i=p[i]
        return ret
    def execute3(self, A):
        ret=0
        v=[0]*len(A)
        for i in range(len(A)):
            for j in range(i):
                if A[j]<A[i] and v[i]<v[j]:
                    v[i]=v[j]
            v[i]+=1
        ret=max(v)
        return ret

