import sys

real_p = []
p = []
f = {}
ans = {}
id_list = []
kb = {}

def main():
    input_data = sys.stdin.read().strip().split()
    real_n, k = int(input_data[0]), int(input_data[1])
    real_p_input = list(map(float, input_data[2:2+real_n]))

    n = 0
    for i in range(real_n):
        if real_p_input[i] > 1e-4:
            id_list.append(i)
            p.append(real_p_input[i])
            n += 1

    k = min(k, n)

    # Initialize kb with bit counts
    for t in range(1 << n):
        kb[t] = bin(t).count('1')

    # Initialize f and ans dictionaries
    for t in range(1 << n):
        f[t] = 0.0
    for i in range(real_n):
        ans[i] = 0.0

    f[0] = 1.0

    for t in range(1 << n):
        if kb[t] == k:
            for j in range(n):
                if (t & (1 << j)) != 0:
                    ans[id_list[j]] += f[t]
            continue
        total = 0.0
        for j in range(n):
            if (t & (1 << j)) == 0:
                total += p[j]
        if total == 0:
            continue
        q = f[t] / total
        for j in range(n):
            if (t & (1 << j)) == 0:
                next_t = t | (1 << j)
                f[next_t] += p[j] * q

    print(' '.join(f"{ans[i]:.17f}" for i in range(real_n)))

if __name__ == "__main__":
