import sys
import math

def BITS(a):
    return bin(a).count('1')

EPS = 1e-9

def add_vals(f, s):
    return (f[0] + s[0], f[1] + s[1])

def sub_vals(f, s):
    return (f[0] - s[0], f[1] - s[1])

def mult_val(f, w):
    return (f[0] * w, f[1] * w)

def div_val(f, w):
    return (f[0] / w, f[1] / w)

def solve(vr, n, k, p, dp):
    if p[vr] < EPS:
        return 0.0
    size = 1 << n
    for msk in range(size):
        for i in range(size):
            # Initialize dp with None
            # We'll handle only the valid ones in main function
            continue

    # Initialize dp[0]
    dp[0] = (1.0, 0.0)

    for msk in range(1, size):
        if msk & (1 << vr):
            continue
        ri = (0.0, 0.0)
        same = 0.0
        for i in range(n):
            if i != vr:
                if msk & (1 << i):
                    same += p[i]
                    ri = add_vals(ri, mult_val(dp[msk ^ (1 << i)], p[i]))
        denom = 1.0 - same
        if abs(denom) < EPS:
            continue
        dp[msk] = div_val(ri, denom)

    tot = (1.0, 0.0)
    for msk in range(1, size):
        if not (msk & (1 << vr)):
            tot = add_vals(tot, dp[msk])

    alp = (1.0 - tot[1]) / tot[0] if abs(tot[0]) > EPS else 0.0

    bad = (0.0, 0.0)
    for msk in range(size):
        if msk & (1 << vr):
            continue
        if BITS(msk) >= k:
            bad = add_vals(bad, dp[msk])
    result = 1.0 - (alp * bad[0] + bad[1])
    return result

def main():
