    n, k = int(input_lines[0]), int(input_lines[1])
    p = list(map(float, input_lines[2:2+n]))
    size = 1 << n
    dp = [None] * size
    results = []
    for i in range(n):
        results.append(solve(i, n, k, p, dp))
    print(' '.join(f'{res:.12f}' for res in results))

if __name__ == "__main__":
    main()

