		sz[i] = 0;
		sum[i] = 0;

		for (int j = 0; j < n; j++)
			if (((i >> j) & 1) == 1) {
				sz[i]++;
				sum[i] += p[j];
			}
	}

	for (int i = k - 1; i >= 0; i--) {
		coef[i] = 1 - coef[i];

		for (int j = 1; i - j >= 0; j++) coef[i - j] += c[n - 1 - i + j][j] * coef[i];
	}

	for (int i = 0; i < n; i++) {
