    disjoint_set dsu(p);

    for (ll i = 0; i < p; ++i) {
        for (ll j = i; !seen[j]; j = (j * k) % p) {
            seen[j] = true;
            dsu.merge(i, j);
        }
    }

    int c = dsu.comps;
    if (k != 1) --c;

    cout << modpow(p, c) << endl;

    return 0;
}

