#include <string.h>
#include <algorithm>

#define MAXN 1100000
#define MOD 1000000007

using namespace std;

typedef long long int LL;

LL p,K;

LL fastPow(LL base,LL pow)
{
    LL ans=1;
    while(pow)
    {
        if(pow&1) ans=(ans*base)%MOD;
        base=(base*base)%MOD;
        pow>>=1;
    }
    return ans;
}

bool vis[MAXN];

int main()
{
    scanf("%I64d%I64d",&p,&K);
    if(K==0)
    {
        printf("%I64d\n",fastPow(p,p-1));
        return 0;
    }
    else if(K==1)
    {
        printf("%I64d\n",fastPow(p,p));
        return 0;
    }
    int cnt=0;
    for(int i=0;i<p;i++)
    {
        if(vis[i]) continue;
        int size=0;
        LL tmp=i;
        while(!vis[tmp])
        {
            size++;
            vis[tmp]=true;
            tmp=tmp*K%p;
        }
        if(size>1) cnt++;
    }
    printf("%I64d\n",fastPow(p,cnt));
    return 0;
}

