    if (y == 1) return x;
    int tmp = mu(x, y / 2);
    tmp = (1ll * tmp * 1ll * tmp) % mod;
    if (y % 2 == 0) return tmp;
    return (1ll * tmp * 1ll * x) % mod;
}

