import sys
import math
import random

MOD = 1000000007

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))

    def find_set(self, a):
        if self.parent[a] == a:
            return a
        self.parent[a] = self.find_set(self.parent[a])
        return self.parent[a]

    def union_set(self, a, b):
        a = self.find_set(a)
        b = self.find_set(b)
        if a != b:
            if random.randint(0, 1):
                a, b = b, a
            self.parent[b] = a

def count_cycles(p, k):
    dsu = DSU(p)
    for i in range(1, p):
        ki = (k * i) % p
        dsu.union_set(i, ki)

    found = [False] * p
    count = 0
    for i in range(1, p):
        base = dsu.find_set(i)
        if not found[base]:
            found[base] = True
            count += 1
    return count

def count_solutions(p, k):
    if k == 0:
        cycles = p - 1
    elif k == 1:
        cycles = p
    else:
        cycles = count_cycles(p, k)
    result = 1
    for _ in range(cycles):
        result = (result * p) % MOD
    return result

