import sys
from collections import deque

MAXN = 150
MAX_N = 400
INF = float('inf')

class MaxFlow:
    class Edge:
        def __init__(self, t, rev, cap, f):
            self.t = t
            self.rev = rev
            self.cap = cap
            self.f = f

    def __init__(self):
        self.adj = [[] for _ in range(MAX_N)]
        self.dist = [-1] * MAX_N
        self.ptr = [0] * MAX_N

    def bfs(self, s, t):
        for i in range(len(self.dist)):
            self.dist[i] = -1
        self.dist[s] = 0
        q = deque([s])
        while q:
            n = q.popleft()
            if self.dist[t] != -1:
                break
            for e in self.adj[n]:
                if self.dist[e.t] == -1 and e.cap != e.f:
                    self.dist[e.t] = self.dist[n] + 1
                    q.append(e.t)
        return self.dist[t] != -1

    def aug(self, n, amt, t):
        if n == t:
            return amt
        for i in range(self.ptr[n], len(self.adj[n])):
            e = self.adj[n][i]
            if self.dist[e.t] == self.dist[n] + 1 and e.cap != e.f:
                flow = self.aug(e.t, min(amt, e.cap - e.f), t)
                if flow != 0:
                    e.f += flow
                    self.adj[e.t][e.rev].f -= flow
                    return flow
            self.ptr[n] += 1
        return 0

    def add(self, u, v, cap=1, rcap=0):
        self.adj[u].append(MaxFlow.Edge(v, len(self.adj[v]), cap, 0))
        self.adj[v].append(MaxFlow.Edge(u, len(self.adj[u]) - 1, rcap, 0))

    def calc(self, s, t):
        flow = 0
        while self.bfs(s, t):
            for i in range(len(self.ptr)):
                self.ptr[i] = 0
            while True:
                df = self.aug(s, INF, t)
                if df == 0:
                    break
                flow += df
        return flow

    def clear(self):
        self.adj = [[] for _ in range(MAX_N)]

