            connect(g[linear(t, r, c)], g[linear(t + 1, r_, c_)], INF);
          }
        }
      }
      // spread
      vll z_;
      for (auto e : z) {
        l r, c; tie(r, c) = e;
        for (l d = 0; d < 4; d++) {
          l r_ = r + dr[d];
          l c_ = c + dc[d];
          if (r_ < 0 or r_ >= n or c_ < 0 or c_ >= n or lab[r_][c_] != '0')
            continue;
          z_.emplace_back(r_, c_);
          lab[r_][c_] = 'Z';
        }
      }
      swap(z_, z);
    }
    cout << max_flow(g, source, sink) << '\n';
  }
}

