import sys
from collections import deque

# Functions and classes for Max Flow (Dinic's Algorithm)
class FlowEdge:
    def __init__(self, v, u, cap):
        self.v = v
        self.u = u
        self.cap = cap
        self.flow = 0

class Dinic:
    def __init__(self, n, s, t):
        self.n = n
        self.s = s
        self.t = t
        self.edges = []
        self.adj = [[] for _ in range(n)]
        self.level = [-1] * n
        self.ptr = [0] * n
        self.q = deque()

    def add(self, v, u, cap):
        edge_idx = len(self.edges)
        self.edges.append(FlowEdge(v, u, cap))
        self.edges.append(FlowEdge(u, v, 0))
        self.adj[v].append(edge_idx)
        self.adj[u].append(edge_idx + 1)

    def bfs(self):
        self.level = [-1] * self.n
        self.level[self.s] = 0
        self.q.clear()
        self.q.append(self.s)

        while self.q:
            v = self.q.popleft()
            for viz in self.adj[v]:
                e = self.edges[viz]
                if e.cap - e.flow < 1:
                    continue
                u = e.u
                if self.level[u] != -1:
                    continue
                self.level[u] = self.level[v] + 1
                self.q.append(u)
        return self.level[self.t] != -1

    def dfs(self, v, pushed):
        if pushed == 0:
            return 0
        if v == self.t:
            return pushed
        while self.ptr[v] < len(self.adj[v]):
            viz = self.adj[v][self.ptr[v]]
            e = self.edges[viz]
            u = e.u
            if self.level[v] + 1 != self.level[u] or e.cap - e.flow < 1:
                self.ptr[v] += 1
                continue
            tr = self.dfs(u, min(pushed, e.cap - e.flow))
            if tr == 0:
                self.ptr[v] += 1
                continue
            e.flow += tr
            self.edges[viz ^ 1].flow -= tr
            return tr
        return 0

    def flow(self):
        total_flow = 0
        while self.bfs():
            self.ptr = [0] * self.n
            while True:
                pushed = self.dfs(self.s, 10**18)
                if pushed == 0:
                    break
                total_flow += pushed
        return total_flow

