    for(int x = 0; x < n; x++) {
    	for(int y = 0; y < n; y++) {
    		if(lab[x][y] == 'Z' || lab[x][y] == 'Y')
    			continue;
    		add_edge(src, n*x + y, lab[x][y] - '0');
    		add_edge(n*n + n*x + y, dst, rea[x][y] - '0');
