    dx = [1, 0, 0, -1]
    dy = [0, 1, -1, 0]
    while q:
        (px, py), psecond = q.popleft()
        if visited[px][py]:
            continue
        visited[px][py] = 1
        dist[px][py] = psecond
        for i in range(4):
            tx = dx[i] + px
