import sys
from collections import deque

MAXN = 256
MAXT = 64
MAXE = MAXN * MAXN
INF = 10**9

class Dinic:
    class Edge:
        def __init__(self, u, v, f, c, nx):
            self.u = u
            self.v = v
            self.f = f
            self.c = c
            self.nx = nx

    def __init__(self):
        self.e = [None] * MAXE
        self.n = 0
        self.m = 0
        self.src = 0
        self.dst = 0
        self.head = [-1] * MAXN
        self.work = [0] * MAXN
        self.d = [-1] * MAXN

    def init(self, n, src, dst):
        self.n = n
        self.src = src
        self.dst = dst
        self.m = 0
        for i in range(n):
            self.head[i] = -1

    def addEdge(self, u, v, c):
        self.e[self.m] = self.Edge(u, v, 0, c, self.head[u])
        self.head[u] = self.m
        self.m += 1
        self.e[self.m] = self.Edge(v, u, 0, 0, self.head[v])
        self.head[v] = self.m
        self.m += 1

    def _bfs(self):
        q = deque()
        self.d = [-1] * self.n
        self.d[self.src] = 0
        q.append(self.src)
        while q:
            k = q.popleft()
            i = self.head[k]
            while i != -1:
                e_i = self.e[i]
                if e_i.f < e_i.c and self.d[e_i.v] == -1:
                    self.d[e_i.v] = self.d[k] + 1
                    q.append(e_i.v)
                i = e_i.nx
        return self.d[self.dst] != -1

    def _dfs(self, u, f):
        if u == self.dst:
            return f
        i = self.work[u]
        while i != -1:
            e_i = self.e[i]
            if e_i.f < e_i.c and self.d[e_i.v] == self.d[u] + 1:
                minf = self._dfs(e_i.v, min(f, e_i.c - e_i.f))
                if minf > 0:
                    e_i.f += minf
                    self.e[i ^ 1].f -= minf
                    return minf
            i = e_i.nx
        return 0

    def maxFlow(self):
        ret = 0
        while self._bfs():
            self.work = self.head[:]
            while True:
                delta = self._dfs(self.src, INF)
                if delta == 0:
                    break
                ret += delta
        return ret

