for i in range(1, n + 1):
    s = input_str[index]
    index += 1
    for j in range(1, n + 1):
        c = s[j-1]
        if c.isdigit():
            sci[i][j] = int(c)
        elif c == 'Y':
            maze[0][i][j] = 1
        elif c == 'Z':
            maze[0][i][j] = 2

# Read capacity
