    s = input_str[index]
    index += 1
    for j in range(1, n + 1):
        if s[j-1].isdigit():
            cap[i][j] = int(s[j-1])

# Helper function to get node id
def get_id(x, y, k):
    return (x - 1) * n + y + k * n * n

# Graph represented as adjacency list
size = 2 + 2 * n * n * 2  # total node count for the flow network
max_nodes = size
head = [-1] * (max_nodes)
edges = []

def addedge(u, v, w):
    edges.append([u, v, w])
    edges.append([v, u, 0])  # reverse edge with 0 capacity
    edge_idx = len(edges)
    return edge_idx - 2

# Build initial graph
def init_graph():
    for _ in range(max_nodes):
        head[_] = -1
    global edges
    edges.clear()

# Adding edges to the graph
def add_edge(u, v, w):
    edges.append([u, v, w])
    edges.append([v, u, 0])
    head[u] = len(edges) - 2
    return len(edges) - 2

# Dinic's algorithm for max flow
def bfs(s, t, d, now):
    for i in range(max_nodes):
        d[i] = 0
    q = deque()
    q.append(s)
    d[s] = 1
    now[s] = head[s]
    while q:
        u = q.popleft()
        i = head[u]
        while i != -1:
            v = edges[i][1]
            w = edges[i][2]
            if d[v] == 0 and w > 0:
                d[v] = d[u] + 1
                now[v] = head[v]
                if v == t:
                    return True
                q.append(v)
            i = edges[i][3]
    return False

def dinic_flow(s, t, flow, d, now):
    if s == t:
        return flow
    res = flow
    i = now[s]
    while i != -1:
        u, v, w = edges[i]
        if w > 0 and d[v] == d[s] + 1:
            k = dinic_flow(v, t, min(res, w), d, now)
            if k > 0:
                edges[i][2] -= k
                edges[i ^ 1][2] += k
                res -= k
                if res == 0:
                    break
        now[s] = edges[i][3]
        i = edges[i][3]
    return flow - res

def solve(s, t):
    total = 0
    while True:
        d = [0] * max_nodes
        now = [0] * max_nodes
        if not bfs(s, t, d, now):
            break
        total += dinic_flow(s, t, inf, d, now)
    return total

# Initialize graph and structures
