class NetworkFlow:
    class Node:
        def __init__(self, v, w, rev):
            self.v = v
            self.w = w
            self.rev = rev

    def __init__(self, V, s, t):
        self.adj = [[] for _ in range(V)]
        self.lev = [-1] * V
        self.edge_tried = [0] * V
        self.st = s
        self.ed = t

    def set_edge(self, u, v, fl):
        sz1 = len(self.adj[v])
        sz2 = len(self.adj[u])
        self.adj[u].append(self.Node(v, fl, sz1))
        self.adj[v].append(self.Node(u, 0, sz2))

    def assign_level(self):
        from collections import deque
        for i in range(len(self.lev)):
            self.lev[i] = -1
        self.lev[self.st] = 0
        queue = deque([self.st])
        while queue:
            now = queue.popleft()
            for node in self.adj[now]:
                nxt = node.v
                if self.lev[nxt] == -1 and node.w != 0:
                    self.lev[nxt] = self.lev[now] + 1
                    queue.append(nxt)
        return self.lev[self.ed] != -1

    def dfs(self, now, fl):
        if now == self.ed:
            return fl
        i = self.edge_tried[now]
        while i < len(self.adj[now]):
            nxt_node = self.adj[now][i]
            nxt = nxt_node.v
            if self.lev[nxt] == self.lev[now] + 1 and nxt_node.w != 0:
