                    dis[nx][ny] = dis[x][y] + 1
                    if tim[nx][ny] > dis[nx][ny]:
                        q.append((nx, ny))
    return dis

# Graph structure for Dinic's algorithm
class Dinic:
    def __init__(self, N, M):
        self.N = N
        self.M = M
        self.fst = [-1] * N
        self.vv = [0] * M
        self.nxt = [0] * M
        self.cap = [0] * M
        self.flow = [0] * M
        self.e = 0

    def init(self):
        for i in range(self.N):
            self.fst[i] = -1
        self.e = 0

    def add(self, u, v, c):
        self.vv[self.e] = v
        self.nxt[self.e] = self.fst[u]
        self.cap[self.e] = c
        self.flow[self.e] = 0
        self.fst[u] = self.e
        self.e += 1

        self.vv[self.e] = u
        self.nxt[self.e] = self.fst[v]
        self.cap[self.e] = 0
        self.flow[self.e] = 0
        self.fst[v] = self.e
        self.e += 1

    def bfs(self, s, t):
        self.d = [-1] * self.N
        self.d[s] = 0
        q = deque()
        q.append(s)
        while q:
            u = q.popleft()
            i = self.fst[u]
            while i != -1:
                v = self.vv[i]
                if self.d[v] == -1 and self.cap[i] > self.flow[i]:
                    self.d[v] = self.d[u] + 1
                    q.append(v)
                i = self.nxt[i]
        return self.d[t] != -1

    def dfs(self, u, t, a, cur):
        if u == t or a == 0:
            return a
        ret = 0
        i = cur[u]
