                    ret += f
                    a -= f
                    if a == 0:
                        break
            i = self.nxt[i]
        cur[u] = i
        return ret

    def max_flow(self, s, t):
        flow = 0
        while self.bfs(s, t):
            cur = self.fst[:]
            flow += self.dfs(s, t, float('inf'), cur)
        return flow

