char a[15][15];
char b[15][15];
int dist[15][15];
bool used[15][15];

bool ok(int x, int y) {
    return 0 <= x && x < n &&
           0 <= y && y < n &&
           a[x][y] != 'Y' &&
           a[x][y] != 'Z';
}

void bfsDeath(int x, int y) {
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            dist[i][j] = INF;
        }
    }

    queue <int> X, Y;
    dist[x][y] = 0;
    X.push(x);
    Y.push(y);

    while (!X.empty()) {
        assert(!Y.empty());

        int curx = X.front();
        int cury = Y.front();

        X.pop();
        Y.pop();

        for (int k = 0; k < 4; k++) {
            int tx = curx + dx[k];
            int ty = cury + dy[k];

            if (ok(tx, ty) && dist[tx][ty] == INF) {
                dist[tx][ty] = dist[curx][cury] + 1;
                X.push(tx);
                Y.push(ty);
            }
        }
    }
}

void runBFS(int x, int y) {
    queue <int> X, Y, lev;
    memset(used, false, sizeof used);

    used[x][y] = true;
    X.push(x);
    Y.push(y);
    lev.push(0);

    while (!X.empty()) {
        assert(!Y.empty());

        int curx = X.front();
        int cury = Y.front();
        int curlev = lev.front();

        X.pop();
        Y.pop();
        lev.pop();

