        a1, b1 = fa['a'], fa['b']
        a2, b2 = fb['a'], fb['b']

        left = abs(x * b1 * b2 - a1 * b2 * y)
        right = abs(x * b1 * b2 - a2 * b1 * y)

        if left < right:
            return -1
        elif left > right:
