import sys

INF = 10**18
ans = 0
dpr = []

def solve(n):
    global dpr
    if n == 0:
        return 0
    if len(dpr) > n and dpr[n] != -1:
        return dpr[n]
    lastdif = INF
    x = 1
    i = 0
    while True:
        if abs(x - n) > lastdif:
            break
        lastdif = abs(x - n)
        x = x * 10 + 1
        i += 1
    x //= 10
    if x > n and x // 10:
        if len(dpr) > n:
            return min(i + solve(abs(x - n)), i - 1 + solve(abs(x // 10 - n)))
        return min(i + solve(abs(x - n)), i - 1 + solve(abs(x // 10 - n)))
    if len(dpr) > n:
        dpr[n] = i + solve(abs(x - n))
        return dpr[n]
    return i + solve(abs(x - n))

def main():
    global dpr
    input_value = sys.stdin.read().strip()
    n = int(input_value)
    # Initialize memoization array with -1
    dpr = [-1] * (10**7 + 1)
    print(solve(n))

