def num(n):
    count = 0
    while n:
        n //= 10
        count += 1
    return count

def find(n):
    ex = num(n)
    cur = 0
    ad = 1
    for _ in range(ex):
        cur += ad
        ad *= 10
    if cur <= n:
        return cur
    return (cur - 1) // 10

def process(n):
    if n <= 6:
        return n
    if n <= 11:
        return 13 - n
    less = find(n)
    more = less * 10 + 1
    if n % less == 0:
        if n <= more // 2 + less:
            return num(less) * n // less
        return num(more) + process(more - n)
    else:
        _m = (n // less) * less
        res = process(_m) + process(n - _m)
        if n > more // 2:
            res = min(process(_m) + process(n - _m), num(more) + process(more - n))
        return res

