# Fast modular exponentiation
def fpm(a, b):
    result = 1
    base = a % p
    exp = b
    while exp > 0:
        if exp & 1:
            result = (result * base) % p
        base = (base * base) % p
        exp >>= 1
    return result

# Define lll class for bitset operations
class lll:
    def __init__(self):
        self.a = 0
        self.b = 0

    def set_bit(self, x):
        if x < 64:
            self.a |= 1 << x
        else:
            self.b |= 1 << (x - 64)

    def reset(self):
        self.a = 0
        self.b = 0

    def __ior__(self, other):
        self.a |= other.a
        self.b |= other.b
        return self

    def __eq__(self, other):
        return self.a == other.a and self.b == other.b

    def __getitem__(self, index):
        if index < 64:
            return (self.a & (1 << index)) != 0
        else:
            return (self.b & (1 << (index - 64))) != 0

