    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9
    x = (x ^ (x >> 27)) * 0x94d049bb133111eb
    return x ^ (x >> 31)

# Generate a fixed random seed based on current time
FIXED_RANDOM = splitmix64(int(time.time() * (random.randint(1, 1 << 50) | 1)))

def safe_hash(x):
    return splitmix64(x ^ FIXED_RANDOM)

MOD = 10 ** 9 + 7

class mod_int:
    def __init__(self, v=0):
        if v < 0:
            v = v % MOD + MOD
        if v >= MOD:
            v %= MOD
        self.val = v

    @staticmethod
    def mod_inv(a, m=MOD):
        g, r, x, y = m, a, 0, 1
        while r != 0:
            q = g // r
            g, r = r, g % r
            x, y = y, x - q * y
        return x if x >= 0 else x + m

    def __int__(self):
        return self.val

    def __iadd__(self, other):
        self.val += other.val
        if self.val >= MOD:
            self.val -= MOD
        return self

    def __isub__(self, other):
        self.val -= other.val
        if self.val < 0:
            self.val += MOD
        return self

    def __imul__(self, other):
        self.val = (self.val * other.val) % MOD
        return self

    def __itruediv__(self, other):
        return self.__imul__(other.inv())

    def __add__(self, other):
        res = mod_int(self.val)
        res += other
        return res

    def __sub__(self, other):
        res = mod_int(self.val)
        res -= other
        return res

    def __mul__(self, other):
        res = mod_int(self.val)
        res *= other
        return res

    def __truediv__(self, other):
        res = mod_int(self.val)
        res /= other
        return res

    def __pos__(self):
        return self

    def __neg__(self):
        return mod_int(0) if self.val == 0 else mod_int(MOD - self.val)

    def __eq__(self, other):
        return self.val == other.val

    def __ne__(self, other):
        return self.val != other.val

    def inv(self):
        return mod_int(self.mod_inv(self.val))

    def pow(self, p):
        assert p >= 0
        result = mod_int(1)
        a = mod_int(self.val)
        while p > 0:
            if p & 1:
                result *= a
            a *= a
            p >>= 1
        return result

def main():
