int ksm(int x,int y)
{
	int ans=1;
	while (y)
	{
		if (y&1) ans=(LL)ans*x%MOD;
		x=(LL)x*x%MOD;y>>=1;
	}
	return ans;
}

void init()
{
	bin[0]=1;
	for (int i=1;i<=20;i++) bin[i]=bin[i-1]*2;
	scanf("%d",&n);
	int inv=ksm(100,MOD-2);
	for (int i=1;i<=n;i++)
		for (int j=1;j<=n;j++)
			scanf("%d",&p[i][j]),p[i][j]=(LL)p[i][j]*inv%MOD;
	while (n<6) n++,p[n][n]=1;
}

