	if (x>3) return 1;
	for (int i=1;i<=3;i++)
		if (!vis[i]&&ma[a[x]][b[i]])
		{
			vis[i]=1;
			bool flag=get_match(x+1);
			vis[i]=0;
			if (flag) return 1;
		}
	return 0;
}

void dfs2(int x,int y,int pro)
