//#pragma GCC target("sse,sse2,sse3,ssse3,sse4,popcnt,abm,mmx,avx,tune=native")
using namespace std; 

const int N = 1e6 + 100, OO = 1e9 + 7, M = 1e9 + 7, P = 6151, T = 2e3, SQ = 280, lg = 64, lg2 = 34;
typedef pair <int, int> pii;
int n, d;
vector <int> v;

struct node {
	int dp[lg2][lg2], cnt[lg2][lg2];
	bool mark[lg2], tark[lg2];
	void mrg(node &nd) {
		for(int i = 0; i <= d; i++) {
			for(int j = 0; j <= d; j++) {
				cnt[i][j] = 0;
				for(int k = 0; k <= d; k++) 
					cnt[i][j] = (cnt[i][j] + dp[k][j] * nd.dp[i][k]) % M;
			}
		}
		for(int i = 0; i < d; i++) {
			if(mark[i] == true && nd.mark[i] == false) {
				for(int j = 0; j <= d; j++)
					cnt[i][j] = dp[i][j];
			}
			if(mark[i] == false && nd.mark[i] == true) { 
				for(int j = 0; j <= d; j++)
					cnt[j][i] = nd.dp[j][i];
			}
			mark[i] |= nd.mark[i];
		}
		for(int i = 0; i <= d; i++)
			for(int j = 0; j <= d; j++)
				dp[i][j] = cnt[i][j];
	}
	void clean() {
		for(int i = 0; i <= d; i++)
			for(int j = 0; j <= d; j++)
				dp[i][j] = cnt[i][j] = 0;
	}
	void shift(int x) {
		for(int i = 0; i <= d; i++)
			for(int j = 0; j <= d; j++)
				cnt[i][j] = 0;
		for(int i = 0; i < d; i++) {
			for(int j = 0; j < d; j++) 
				cnt[(i + x) % d][(j + x) % d] = dp[i][j];	
			cnt[(i + x) % d][d] = dp[i][d];
		}
		for(int i = 0; i < d; i++)
			cnt[d][(i + x) % d] = dp[d][i];
		cnt[d][d] = dp[d][d];
		for(int i = 0; i <= d; i++)
			for(int j = 0; j <= d; j++)
				dp[i][j] = cnt[i][j];
		for(int i = 0; i < d; i++)
			tark[i] = mark[(i + x) % d];
		for(int i = 0; i < d; i++)
			mark[i] = tark[i];
	}
} md[lg + 5], hp[lg + 5], ht;

node get(int x) {
	int h = x, pw = 1, t = -1;
	while(h >= d)
		h /= d, pw *= d, t++;
	x %= pw;
	if(t == -1) 
		return hp[h];
	node ans = md[t];
	ht = md[t];
	for(int i = 1; i < h; i++) {
		ht.shift(1);
		ans.mrg(ht);
	}
	ht = get(x);
	ht.shift(h);	
	ans.mrg(ht);
	return ans;
}

