		v.pb(n % d);
		n /= d;
	}
	hp[0].dp[d][d] = 2;
	hp[0].dp[d][0] = -1;
	hp[0].dp[0][d] = 1;
	hp[0].mark[0] = true;
	md[0] = hp[0];
	for(int i = 1; i < d; i++) {
		hp[i].dp[d][d] = 2;
		hp[i].dp[d][i] = -1;
		hp[i].dp[i][d] = 1;
		hp[i].mark[i] = true;
		md[0].mrg(hp[i]);
		hp[i] = md[0];
	}
	for(int i = 1; i <= (int)v.size(); i++) {
		md[i] = md[i - 1];
		ht = md[i - 1];
		for(int j = 1; j < d; j++) {
			ht.shift(1);
			md[i].mrg(ht);
		}
	}
	node ans = get(m);
	cout << ans.dp[d][d] << endl;
	return 0;
}
