        r *= o
        return r

    def __truediv__(self, o):
        r = FiniteField(self.x)
        r /= o
        return r

    def __iadd__(self, o):
        self.x = (self.x + o.x) % P
        return self

    def __isub__(self, o):
        self.x = (self.x + P - o.x) % P
        return self

    def __imul__(self, o):
        self.x = (self.x * o.x) % P
        return self

    def __itruediv__(self, o):
        p = P - 2
        base = o
        result = FiniteField(1)
        while p > 0:
            if p % 2 == 1:
                result *= base
            base *= base
            p //= 2
