class Matrix:
    def __init__(self, size):
        self.a = [[0] * (size + 1) for _ in range(size + 1)]
        self.n = size

    def init(self):
        for i in range(1, self.n + 1):
            for j in range(1, self.n + 1):
                self.a[i][j] = 0

    def set(self):
        self.init()
        for i in range(1, self.n + 1):
            self.a[i][i] = 1

    def __mul__(self, rhs):
        ans = Matrix(self.n)
        tmp = [[0] * (self.n + 1) for _ in range(self.n + 1)]
        MODLL = (LL := 1 * 10 ** 18) * MOD
        for i in range(1, self.n + 1):
            for j in range(1, self.n + 1):
                tmp[i][j] = 0
        for i in range(1, self.n + 1):
