def pwr(x, y):
    z = 1
    while y:
        if y & 1:
            z = (z * x) % Mo
        y >>= 1
        x = (x * x) % Mo
    return z

def inc(a, y):
    return (a + y) % Mo

def dec(a, y):
    return (a - y) + Mo if (a - y) < 0 else (a - y)

def FWT(a, length):
    i = 1
    while i < length:
        for j in range(0, length, i << 1):
            for k in range(i):
                a[j + k + i] = inc(a[j + k + i], a[j + k])
        i <<= 1

def IFWT(a, length):
    i = 1
    while i < length:
        for j in range(0, length, i << 1):
            for k in range(i):
                a[j + k + i] = dec(a[j + k + i], a[j + k])
        i <<= 1

def get_ln():
    global h, p, n, Mo, inv
    p = [0] * (n + 1)
    for i in range(1, n + 1):
        p[i] = h[i] * i % Mo
        for j in range(1, i):
            p[i] = dec(p[i], p[j] * h[i - j] % Mo * j)
        p[i] = p[i] * inv[i] % Mo
    for i in range(n + 1):
        h[i] = (p[i] + Mo) % Mo

def get_exp():
