# Import necessary modules
import sys
import math

# Function to check max
def chkmax(x, y):
    if x < y:
        return y, True
    return x, False

# Function to check min
def chkmin(x, y):
    if x > y:
        return y, True
    return x, False

# Function to get integer input
def geti():
    return int(sys.stdin.read())

# Fast exponentiation
def fpow(a, b, c=1):
    result = c
    while b:
        if b & 1:
            result = result * a % P
        a = a * a % P
        b >>= 1
    return result

# Initialize factorials and inverses
def init(n):
    fac[0] = 1
    for i in range(1, n + 1):
        fac[i] = fac[i - 1] * i % P
    ifac[n] = fpow(fac[n], P - 2)
    for i in range(n - 1, -1, -1):
        ifac[i] = ifac[i + 1] * (i + 1) % P
    inv[1] = 1
    for i in range(2, n + 1):
        inv[i] = (P - P // i) * inv[P % i] % P

# Add and subtract functions
def add(x, y):
    x += y
    if x >= P:
        x -= P
    return x

def sub(x, y):
    x -= y
    if x < 0:
        x += P
    return x

# Fast Möbius transform (FMT)
def FMT(f, n):
    length = 1
    while length < n:
        for i in range(0, n, length * 2):
            for j in range(length):
                f[i + j + length] = add(f[i + j + length], f[i + j])
        length <<= 1

# Inverse Möbius transform (IFMT)
def IFMT(f, n):
    length = 1
    while length < n:
        for i in range(0, n, length * 2):
            for j in range(length):
                f[i + j + length] = sub(f[i + j + length], f[i + j])
        length <<= 1

# Polynomial logarithm
def ln(f, g, n):
    g[0] = 0
    for i in range(1, n):
        g[i] = 0
        for j in range(1, i):
            g[i] = (g[i] + f[i - j] * g[j] % P * j) % P
        g[i] = (f[i] + g[i] * (P - inv[i])) % P

# Polynomial exponential
def exp(f, g, n):
    g[0] = 1
    for i in range(1, n):
        g[i] = 0
        for j in range(1, i + 1):
            g[i] = (g[i] + g[i - j] * f[j] % P * j) % P
        g[i] = (g[i] * inv[i]) % P

# Main execution
if __name__ == "__main__":
    # Read inputs
    input_data = sys.stdin.read().split()
    n = int(input_data[0])
    k = int(input_data[1])
    P = int(input_data[2])

    # Initialize factorials and inverses
    fac = [0] * (300010)
    ifac = [0] * (300010)
    inv = [0] * (300010)
    init(n)

