        m = int(math.log2(n)) + 1
        size = 1 << m
        f = [[0] * size for _ in range(m + 1)]
        # Populate f with inverse factorial
        for i in range(size):
            f[bin(i).count("1")][i] = ifac[i]
        # Perform FMT on each row
        for i in range(m + 1):
            FMT(f[i], size)

        F = [0] * (m + 1)
        G = [0] * (m + 1)
        for i in range(size):
            for j in range(m + 1):
                F[j] = f[j][i]
            ln(F, G, m + 1)
            for j in range(m + 1):
                G[j] = G[j] * k % P
