        inv = [1] * (size + 1)
        for i in range(1, size + 1):
            fac[i] = fac[i-1] * i % P
        ifac[size] = fpow(fac[size], P - 2, P)
        for i in range(size - 1, -1, -1):
            ifac[i] = ifac[i + 1] * (i + 1) % P
        inv[1] = 1
        for i in range(2, size + 1):
            inv[i] = (P - P // i) * inv[P % i] % P

        def popcount(x):
            return bin(x).count('1')

        # Initialize f as a 2D list
        f = [[0] * size for _ in range(m + 1)]
        for i in range(size):
            f[popcount(i)][i] = ifac[i]

