# Modular arithmetic functions
def mod_pow(x, n, m=mod):
    res = 1
    while n:
        if n & 1:
            res = res * x % m
        x = x * x % m
        n >>= 1
    return res

def inv(a, p=mod):
    if a == 1:
        return 1
    else:
        return (1 - p * inv(p % a, a)) // a + p

class ModInt:
    def __init__(self, value=0):
        self.n = value % mod

    def __add__(self, other):
        res = ModInt(self.n + other.n)
        if res.n >= mod:
            res.n -= mod
        return res

    def __sub__(self, other):
        res = ModInt(self.n - other.n)
        if res.n < 0:
            res.n += mod
        return res

    def __mul__(self, other):
        return ModInt(self.n * other.n)

    def __truediv__(self, other):
        return self * ModInt(inv(other.n, mod))

    def __pow__(self, power):
        if power == 0:
            return ModInt(1)
        res = (self * self) ** (power // 2)
        if power % 2:
            res = res * self
        return res

    def __int__(self):
        return self.n

# Initialize factorials and inverse factorials
