		pll d[N + 2][N + 1];

		void solve() {
			forn (i, n + 1) {
				forn (j, n + 1) {
					if (!i || !j) {
						c[i][j] = 1;
						continue;
					}
					c[i][j] = (c[i - 1][j] + c[i][j - 1]) % mod;
