# Modular exponentiation
def mod_pow(base, exp, modulus):
    result = 1
    base %= modulus
    while exp > 0:
        if exp & 1:
            result = (result * base) % modulus
        base = (base * base) % modulus
        exp >>= 1
    return result

# Class for modular arithmetic
class Mint:
    def __init__(self, value, mod):
        self.x = value % mod
        self.mod = mod

    def __add__(self, other):
        return Mint(self.x + other.x, self.mod)

    def __sub__(self, other):
        return Mint(self.x - other.x, self.mod)

    def __mul__(self, other):
        return Mint(self.x * other.x, self.mod)

    def __truediv__(self, other):
        return self * other.inv()

    def __pow__(self, power):
        return Mint(mod_pow(self.x, power, self.mod), self.mod)

    def inv(self):
        # Extended Euclidean Algorithm for modular inverse
        return Mint(pow(self.x, -1, self.mod), self.mod)

    def __eq__(self, other):
        return self.x == other.x

    def __ne__(self, other):
        return self.x != other.x

    def __repr__(self):
        return str(self.x)

# Function to generate binomial coefficients (nCr)
