import sys

def spow(a, b, M):
    r = 1
    while b:
        if b % 2:
            r = r * a % M
        a = a * a % M
        b //= 2
    return r

def Inv(a, M):
    b = M - 2
    r = 1
    while b:
        if b % 2:
            r = r * a % M
        a = a * a % M
        b //= 2
    return r

def f(c, p, M):
    if p == 0:
        return 1
    return spow(c + 1, p - 1, M) * (c + 1 - p) % M

N = 515

