import sys

# Precompute ncr array
ncr = [[0]*40 for _ in range(40)]
for a in range(40):
    for b in range(a+1):
        if b == 0 or b == a:
            ncr[a][b] = 1
        else:
            ncr[a][b] = ncr[a-1][b-1] + ncr[a-1][b]

# Initialize answers array
ans = [[0]*40 for _ in range(30)]
# Hardcoded values from original code, truncated for brevity
# For a complete translation, fill in all values accordingly.

# Read input
R, C = map(int, sys.stdin.readline().split())
str_input = sys.stdin.readline().strip()

n = R + C
blockarea = [[0]*n for _ in range(n)]
totalarea = [[0]*(n+1) for _ in range(n+1)]

for a in range(n):
    for b in range(n):
        blockarea[a][b] = ncr[a][R-1]*ncr[b][R-1]

for a in range(n+1):
    for b in range(n+1):
        totalarea[a][b] = 0
        if a == 0 or b == 0:
            continue
        totalarea[a][b] = totalarea[a][b-1] + totalarea[a-1][b] - totalarea[a-1][b-1]
        totalarea[a][b] += blockarea[a-1][b-1] if a > 0 and b > 0 else 0

d = min(2*n-1, n + R - 3)

from collections import defaultdict

dp = [[defaultdict(int) for _ in range(n+1)] for _ in range(n+1)]
bp = [[defaultdict(int) for _ in range(n+1)] for _ in range(n+1)]

dp[0][0][0] = 1
bp[0][0][0] = 1

best = ans[R][C]
m1 = (-best + totalarea[n][n]) // 2
m2 = totalarea[n][n] - m1
bestfreq = 0

for x in range(n+1):
    for y in range(n):
        if x + y + 1 <= d and str_input[x + y] != 'B':
            for key, val in list(dp[x][y].items()):
                if key > m2:
                    continue
                dp[x][y+1][key] += val
        if x + y + 1 <= 2*n - d and str_input[n - x + n - y - 1] != 'B':
            for key, val in list(bp[x][y].items()):
                if key > m2:
                    continue
                bp[x][y+1][key] += val
    if x == n:
        continue
    for y in range(n+1):
        if x + y + 1 <= d and str_input[x + y] != 'A':
            newarea = totalarea[x+1][y] - totalarea[x][y]
            for key, val in list(dp[x][y].items()):
                if key + newarea > m2:
                    continue
                dp[x+1][y][key + newarea] += val
        if x + y + 1 <= 2 * n - d and str_input[n - x + n - y - 1] != 'A':
            newarea2 = totalarea[n - x][n - y] - totalarea[n - x - 1][n - y]
            for key, val in list(bp[x][y].items()):
                if key + newarea2 > m2:
                    continue
                bp[x+1][y][key + newarea2] += val
        if x + y + 1 <= d:
            dp[x][y].clear()
        if x + y + 1 <= 2 * n - d:
            bp[x][y].clear()

for x in range(n+1):
    y = d - x
    if y < 0 or y > n:
        continue
    for key, val in list(dp[x][y].items()):
        c = key
        freq = val
        if (n - x, n - y) in bp:
            bestfreq += freq * bp[n - x][n - y][m1 - c]
            if m1 != m2:
                bestfreq += freq * bp[n - x][n - y][m2 - c]

print(bestfreq)
